FRONTEND_PREDICATE_SEMANTICS: dict[str, str] = {
    'BOOL': 'truth',
    'BUILTIN_BOOL': 'truth',
    'CAST_BOOL': 'truth',
    'EQ': 'equality',
    'GE': 'ordering',
    'GT': 'ordering',
    'IN': 'containment',
    'LE': 'ordering',
    'LT': 'ordering',
    'NE': 'equality',
    'NOT': 'truth',
    'NOT_IN': 'containment',
    'STRING_EQ': 'equality',
}

COMPARISON_SCALAR_DOMAINS: dict[str, tuple[int, bool]] = {
    'int': (0, True),
    'float': (0, True),
    'bool': (0, True),
    'str': (1, True),
    'bytes': (2, True),
    'None': (3, False),
}

def frontend_predicate_facts(kind: str, *operands: str | None) -> tuple[bool, bool] | None:
    category = FRONTEND_PREDICATE_SEMANTICS.get(kind)
    if category is None:
        return None
    if len(operands) != (1 if category == 'truth' else 2):
        return False, False
    if category == 'truth':
        exact = operands[0] in COMPARISON_SCALAR_DOMAINS
        return exact, exact
    if category == 'containment':
        return False, False
    left, right = operands
    if category == 'equality' and (left, right) in (('bool', 'bytes'), ('bytes', 'bool'), ('bytes', 'int'), ('bytes', 'str'), ('int', 'bytes'), ('str', 'bytes')):
        return False, False
    lhs = COMPARISON_SCALAR_DOMAINS.get(left) if left is not None else None
    rhs = COMPARISON_SCALAR_DOMAINS.get(right) if right is not None else None
    if lhs is None or rhs is None:
        return False, False
    return True, category == 'equality' or (lhs == rhs and lhs[1])

FRONTEND_COMMUTATIVE_DOMAINS: dict[str, str] = {'ADD': 'numeric', 'BIT_AND': 'i64', 'BIT_OR': 'i64', 'BIT_XOR': 'i64', 'EQ': 'unboxed_scalar', 'MUL': 'numeric', 'NE': 'unboxed_scalar', 'STRING_EQ': 'unboxed_scalar'}

def frontend_can_reorder_commutative(kind: str, *operands: str | None) -> bool:
    if len(operands) != 2:
        return False
    left, right = operands
    domain = FRONTEND_COMMUTATIVE_DOMAINS.get(kind)
    if domain == 'numeric':
        return left in ('int', 'float') and right in ('int', 'float')
    if domain == 'i64':
        return left == right == 'int'
    return domain == 'unboxed_scalar' and left == right and left in ('int', 'float', 'bool', 'None')

