def validate_frontend_kind(kind: str, function_name: str) -> None:
    if kind not in FRONTEND_REGISTERED_KINDS:
        raise ValueError(f"function {function_name!r}: unregistered frontend op kind {kind!r}")


def validate_serialized_kind(kind: str, function_name: str = "<direct>") -> None:
    """Reject unregistered kinds and frontend semantic tokens.

    Preserved wire operations retain their spelling and target-specific
    admission. This check never collapses local binding aliases or invents
    a target support claim for a registered wire operation."""
    if kind in FRONTEND_EFFECT_CLASS:
        raise ValueError(f"function {function_name!r}: frontend operation {kind!r} escaped serialization")
    if kind in SIMPLEIR_BACKEND_PRIVATE_KINDS:
        raise ValueError(f"function {function_name!r}: backend-private SimpleIR op kind {kind!r} escaped frontend serialization")
    if kind not in SIMPLEIR_REGISTERED_KINDS:
        raise ValueError(f"function {function_name!r}: unregistered SimpleIR op kind {kind!r}")


def canonical_kind(kind: str) -> str:
    """Return the canonical wire spelling for *kind*.

    Identity for any kind not in the registry (the overwhelming common
    case: the kind is already canonical). The registry only records the
    alias collapses that exist today (e.g. the floordiv family)."""
    return CANONICAL_KIND.get(kind, kind)
